// Deal Tracker duplicates: 27 audit conflicts + D03008 (Kaizenvest <> Appli).
// D03010 was removed in Phase 1.
const TARGETS = ['D00092','D00109','D00140','D00143','D00773','D00810','D00969','D01055','D01060','D01110','D01156','D01553','D01606','D01658','D01671','D01840','D01870','D02015','D02048','D02136','D02240','D02244','D02303','D02615','D02665','D02750','D02761','D02784','D02873','D02896','D03008'];

const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

const byId = {};
for (const r of rows) {
  const id = String(r.deal_id == null ? '' : r.deal_id).trim();
  if (id) { (byId[id] = byId[id] || []).push(r); }
}

const out = [];
for (const t of TARGETS) {
  const hits = byId[t] || [];
  if (hits.length !== 1) { throw new Error('ABORT: expected 1 row for ' + t + ', found ' + hits.length); }
  const h = hits[0];
  if (String(h.deal_shared == null ? '' : h.deal_shared).trim().toLowerCase() === 'yes') {
    throw new Error('ABORT: ' + t + ' has deal_shared=Yes - refusing to delete a sent row');
  }
  if (!h.row_number) { throw new Error('ABORT: no row_number for ' + t); }
  out.push({ json: { row_number: Number(h.row_number), deal_id: t, investor: h.investor, startup: h.startup } });
}

if (out.length !== TARGETS.length) { throw new Error('ABORT: resolved ' + out.length + ' of ' + TARGETS.length); }

// Descending row order: deleting the highest row first keeps lower row numbers valid.
out.sort(function (a, b) { return b.json.row_number - a.json.row_number; });

for (let i = 1; i < out.length; i++) {
  if (out[i].json.row_number === out[i - 1].json.row_number) { throw new Error('ABORT: duplicate row_number'); }
}
return out;
